PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS clients(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,contact TEXT,email TEXT,phone TEXT);
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT,username TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('admin','manager','operator','viewer','client')),active INTEGER NOT NULL DEFAULT 1,client_id INTEGER REFERENCES clients(id),token_version INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS channels(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,category TEXT,frequency TEXT);
CREATE TABLE IF NOT EXISTS programs(id INTEGER PRIMARY KEY AUTOINCREMENT,channel_id INTEGER REFERENCES channels(id),name TEXT NOT NULL,air_time TEXT,description TEXT);
CREATE TABLE IF NOT EXISTS campaigns(id INTEGER PRIMARY KEY AUTOINCREMENT,client_id INTEGER REFERENCES clients(id),name TEXT NOT NULL,start_date TEXT,end_date TEXT,budget REAL,status TEXT);
CREATE TABLE IF NOT EXISTS creatives(id INTEGER PRIMARY KEY AUTOINCREMENT,campaign_id INTEGER REFERENCES campaigns(id),name TEXT NOT NULL,duration_seconds INTEGER,reference_url TEXT);
CREATE TABLE IF NOT EXISTS spots(id INTEGER PRIMARY KEY AUTOINCREMENT,campaign_id INTEGER REFERENCES campaigns(id),channel_id INTEGER REFERENCES channels(id),program_id INTEGER REFERENCES programs(id),creative_id INTEGER REFERENCES creatives(id),planned_at TEXT,price REAL);
CREATE TABLE IF NOT EXISTS airings(id INTEGER PRIMARY KEY AUTOINCREMENT,spot_id INTEGER REFERENCES spots(id),actual_at TEXT,source TEXT,evidence_url TEXT,notes TEXT);
CREATE TABLE IF NOT EXISTS test_runs(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,target_type TEXT NOT NULL,target_url TEXT,notes TEXT,created_by INTEGER REFERENCES users(id),status TEXT NOT NULL DEFAULT 'pending',client_id INTEGER REFERENCES clients(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS test_results(id INTEGER PRIMARY KEY AUTOINCREMENT,run_id INTEGER NOT NULL REFERENCES test_runs(id),test_name TEXT NOT NULL,result TEXT NOT NULL,details TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_test_runs_client ON test_runs(client_id);
